begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.list_my_story_link_repairs(uuid,integer)','execute'),'anonymous cannot execute private discovery');
select ok(not has_function_privilege('anon','public.get_my_story_cat_link(uuid)','execute'),'anonymous cannot read management');
select ok(not has_table_privilege('authenticated','private.story_cat_link_requests','select'),'client cannot read private audit');
select has_function('public','change_my_story_cat_link',array['uuid','uuid','text','bigint','uuid']);
set local session_replication_role=replica;
insert into public.user_profiles(id,public_name,adult_confirmed_at) values
 ('00000000-0000-4000-8000-000000004601','Link author',now()),('00000000-0000-4000-8000-000000004602','Other author',now());
set local session_replication_role=origin;
insert into public.animals(id,primary_alias,visibility) values
 ('00000000-0000-4000-8000-000000004611','Cat A','public'),('00000000-0000-4000-8000-000000004612','Cat B','public');
insert into public.community_posts(id,author_id,cat_id,community_slug,body) values
 ('00000000-0000-4000-8000-000000004621','00000000-0000-4000-8000-000000004601',null,'bishan','Unknown story'),
 ('00000000-0000-4000-8000-000000004622','00000000-0000-4000-8000-000000004601','00000000-0000-4000-8000-000000004611',null,'No neighbourhood');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000004601',true);
select is(public.get_my_story_cat_link('00000000-0000-4000-8000-000000004621')->>'revision','0','historical post starts at revision zero');
select is(public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621','00000000-0000-4000-8000-000000004611','bishan',0,'00000000-0000-4000-8000-000000004631')->>'revision','1','unknown becomes cat A');
select is(public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621','00000000-0000-4000-8000-000000004611','bishan',0,'00000000-0000-4000-8000-000000004631')->>'revision','1','same request replays despite stale expected revision');
select throws_ok($$select public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621',null,'bishan',0,'00000000-0000-4000-8000-000000004631')$$,'P0001','idempotency_conflict','same request changed intent denied');
select throws_ok($$select public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621',null,'bishan',0,'00000000-0000-4000-8000-000000004632')$$,'P0001','story_link_conflict','another stale device cannot overwrite');
select is(public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621','00000000-0000-4000-8000-000000004612','bishan',1,'00000000-0000-4000-8000-000000004633')->>'revision','2','A becomes B');
select is(public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621','00000000-0000-4000-8000-000000004612','bishan',2,'00000000-0000-4000-8000-000000004634')->>'revision','2','same value no-op preserves revision');
select throws_ok($$select public.change_my_story_cat_link('00000000-0000-4000-8000-000000004622',null,null,0,'00000000-0000-4000-8000-000000004635')$$,'P0001','neighbourhood_required','unlink cannot lose both cat and neighbourhood');
select throws_ok($$select public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621',null,'changed-neighbourhood',2,'00000000-0000-4000-8000-000000004636')$$,'22023','invalid_story_link_request','link editor cannot rewrite existing neighbourhood');
reset role;
update public.animals set archived_at=now() where id='00000000-0000-4000-8000-000000004612';
set local role authenticated;
select is(public.get_my_story_cat_link('00000000-0000-4000-8000-000000004621')->>'revision','2','author can repair hidden old cat');
select is((select count(*) from public.list_my_story_link_repairs(null,20)),1::bigint,'owner can discover story needing old-cat repair');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000004602',true);
select is_empty($$select * from public.list_my_story_link_repairs(null,20)$$,'other author cannot discover private repair story');
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select * from public.list_my_story_link_repairs(null,20)$$,'P0001','story_link_unavailable','empty authenticated session cannot list repairs');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000004601',true);
reset role;
insert into private.account_erasure_requests(request_id,target_subject_id) values('00000000-0000-4000-8000-000000004699','00000000-0000-4000-8000-000000004601');
set local role authenticated;
select throws_ok($$select * from public.list_my_story_link_repairs(null,20)$$,'P0001','story_link_unavailable','pending erasure cannot list repairs');
select throws_ok($$select public.get_my_story_cat_link('00000000-0000-4000-8000-000000004621')$$,'P0001','story_link_unavailable','pending erasure cannot manage a link');
select throws_ok($$select public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621',null,'bishan',2,'00000000-0000-4000-8000-000000004698')$$,'P0001','story_link_unavailable','pending erasure cannot change a link');
reset role;
delete from private.account_erasure_requests where request_id='00000000-0000-4000-8000-000000004699';
update public.community_posts set moderation_hidden_at=now() where id='00000000-0000-4000-8000-000000004621';
set local role authenticated;
select is_empty($$select * from public.list_my_story_link_repairs(null,20)$$,'moderation-hidden story never appears in repair discovery');
reset role;
update public.community_posts set moderation_hidden_at=null,deleted_at=now() where id='00000000-0000-4000-8000-000000004621';
set local role authenticated;
select is_empty($$select * from public.list_my_story_link_repairs(null,20)$$,'deleted story never appears in repair discovery');
reset role;
update public.community_posts set deleted_at=null where id='00000000-0000-4000-8000-000000004621';
set local role authenticated;

select is(public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621','00000000-0000-4000-8000-000000004612','bishan',1,'00000000-0000-4000-8000-000000004633')->>'revision','2','success replay survives later cat invisibility');
select throws_ok($$select public.change_my_story_cat_link('00000000-0000-4000-8000-000000004622','00000000-0000-4000-8000-000000004612',null,0,'00000000-0000-4000-8000-000000004637')$$,'P0001','cat_unavailable','new hidden target rejected');
select is(public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621',null,'bishan',2,'00000000-0000-4000-8000-000000004638')->>'revision','3','hidden B can become unknown');
select is(public.change_my_story_cat_link('00000000-0000-4000-8000-000000004622',null,'bishan',0,'00000000-0000-4000-8000-000000004639')->>'communitySlug','bishan','unlink may add missing neighbourhood');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000004602',true);
select throws_ok($$select public.get_my_story_cat_link('00000000-0000-4000-8000-000000004621')$$,'P0001','story_link_unavailable','non-author cannot read management state');
select throws_ok($$select public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621',null,'bishan',3,'00000000-0000-4000-8000-000000004640')$$,'P0001','story_link_unavailable','non-author cannot modify');
reset role;
update public.community_posts set moderation_hidden_at=now() where id='00000000-0000-4000-8000-000000004621';
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000004601',true);
select throws_ok($$select public.change_my_story_cat_link('00000000-0000-4000-8000-000000004621',null,'bishan',2,'00000000-0000-4000-8000-000000004638')$$,'P0001','story_link_unavailable','hidden post prevents even successful replay');
-- Successful publication whose response was lost must be reconciled before mutable cat validation.
select set_config('test.created_story',public.create_community_post_with_media('Lost response story',null,'00000000-0000-4000-8000-000000004611',null,'{}','00000000-0000-4000-8000-000000004641')::text,true);
select set_config('test.created_plain',public.create_community_post('Plain lost response','00000000-0000-4000-8000-000000004611',null,'00000000-0000-4000-8000-000000004642')::text,true);
reset role;
update public.animals set archived_at=now() where id='00000000-0000-4000-8000-000000004611';
set local role authenticated;
select is(public.create_community_post_with_media('Lost response story',null,'00000000-0000-4000-8000-000000004611',null,'{}','00000000-0000-4000-8000-000000004641')::text,current_setting('test.created_story'),'lost media-post response returns original ID after cat hidden');
select is(public.create_community_post('Plain lost response','00000000-0000-4000-8000-000000004611',null,'00000000-0000-4000-8000-000000004642')::text,current_setting('test.created_plain'),'legacy plain post has same reconciliation guarantee');
select is_empty($$select * from public.get_public_community_post(current_setting('test.created_story')::uuid)$$,'reconciled hidden-cat post has no public success summary');
reset role;
select is((select count(*) from public.community_posts where body='Lost response story'),1::bigint,'replay created exactly one story');
update public.community_posts set deleted_at=now() where id=current_setting('test.created_story')::uuid;
set local role authenticated;
select throws_ok($$select public.create_community_post_with_media('Lost response story',null,'00000000-0000-4000-8000-000000004611',null,'{}','00000000-0000-4000-8000-000000004641')$$,'P0001','community_post_deleted','deleted publication is terminal');
reset role;
select is((select body from public.community_posts where id='00000000-0000-4000-8000-000000004621'),'Unknown story','changing cat preserves original body');
select ok((select count(*)>0 from private.story_cat_link_requests where actor_id='00000000-0000-4000-8000-000000004601'),'private audit exists');
delete from public.user_profiles where id='00000000-0000-4000-8000-000000004601';
select is((select count(*) from private.story_cat_link_requests where actor_id='00000000-0000-4000-8000-000000004601'),0::bigint,'erasure deletes private request audit');
select * from finish();
rollback;
